import{_ as a}from"./chunks/chat-diagnostics.HMJaz4jC.js";import{_ as o,o as e,c as r,ai as n}from"./chunks/framework.C33Uq6m-.js";const k=JSON.parse('{"title":"对话诊断","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/chat-diagnostics.md","filePath":"zh/guide/chat-diagnostics.md"}'),l={name:"zh/guide/chat-diagnostics.md"};function i(d,t,s,h,c,g){return e(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="对话诊断" tabindex="-1">对话诊断 <a class="header-anchor" href="#对话诊断" aria-label="Permalink to &quot;对话诊断&quot;">​</a></h1><p>对话诊断页是 LLMxRay 的核心。它把一个功能完整的对话界面，和对模型产出的每一个 token 的深度实时分析结合在一起。</p><p><strong>侧边栏位置：</strong> 对话诊断（第一项） <strong>路由：</strong> <code>/</code></p><p><img src="'+a+'" alt="对话诊断界面"></p><h2 id="界面概览" tabindex="-1">界面概览 <a class="header-anchor" href="#界面概览" aria-label="Permalink to &quot;界面概览&quot;">​</a></h2><p>页面分为两块：</p><ul><li><strong>左侧面板</strong> —— 会话列表，显示所有历史对话及其时间戳、模型名称和 token 数量。</li><li><strong>右侧面板</strong> —— 当前对话区域，包含输入框、流式输出和会话详情标签页。</li></ul><h2 id="开始一段对话" tabindex="-1">开始一段对话 <a class="header-anchor" href="#开始一段对话" aria-label="Permalink to &quot;开始一段对话&quot;">​</a></h2><ol><li>从顶部的<strong>模型下拉框</strong>选择一个模型。嵌入模型会被自动过滤掉，只显示可用于对话的模型。</li><li>在输入区输入你的消息。</li><li>按 <strong>Enter</strong> 或点击发送。</li></ol><p>Token 会逐个流式到达，并带有<strong>置信度着色</strong>：每个 token 的颜色取决于模型生成它的速度。越快的 token 置信度越高（偏绿），越慢的 token 置信度越低（偏橙或偏红）。</p><div class="info custom-block"><p class="custom-block-title">置信度是一个近似值</p><p>由于 Ollama 的 <code>/api/chat</code> 接口不暴露 token 的 logprobs，LLMxRay 用 token 之间的延迟来近似置信度。界面中对此有明确标注。如果需要真实的 logprobs，请使用<a href="./benchmark.html">基准测试</a>功能。</p></div><h2 id="功能" tabindex="-1">功能 <a class="header-anchor" href="#功能" aria-label="Permalink to &quot;功能&quot;">​</a></h2><h3 id="markdown-渲染" tabindex="-1">Markdown 渲染 <a class="header-anchor" href="#markdown-渲染" aria-label="Permalink to &quot;Markdown 渲染&quot;">​</a></h3><p>模型回复会渲染为富文本 Markdown，代码块带语法高亮。</p><h3 id="文件附件" tabindex="-1">文件附件 <a class="header-anchor" href="#文件附件" aria-label="Permalink to &quot;文件附件&quot;">​</a></h3><p>点击附件按钮上传文件。对于<strong>视觉模型</strong>（如 LLaVA），你可以直接粘贴或上传图片，模型会对其进行分析。</p><h3 id="斜杠命令" tabindex="-1">斜杠命令 <a class="header-anchor" href="#斜杠命令" aria-label="Permalink to &quot;斜杠命令&quot;">​</a></h3><p>在输入框中输入 <code>/</code> 即可查看可用的斜杠命令，用于快速操作。</p><h3 id="多轮对话" tabindex="-1">多轮对话 <a class="header-anchor" href="#多轮对话" aria-label="Permalink to &quot;多轮对话&quot;">​</a></h3><p>每段对话都保留完整的消息历史，模型能看到之前的全部消息作为上下文。</p><h3 id="推理控制-v0-4-7" tabindex="-1">推理控制（v0.4.7+） <a class="header-anchor" href="#推理控制-v0-4-7" aria-label="Permalink to &quot;推理控制（v0.4.7+）&quot;">​</a></h3><p>对于报告了 <code>thinking</code> 能力的模型（DeepSeek-R1、QwQ 等），对话设置面板中会出现一个<strong>推理</strong>控件，有三种模式：</p><ul><li><strong>关闭</strong> —— 不发送 <code>think</code> 字段，模型表现为普通对话模型</li><li><strong>开启</strong> —— 在 <code>/api/chat</code> 上发送 <code>think: true</code>，模型会在回答前产生一段内部推理过程</li><li><strong>最大</strong> —— 发送 <code>think: &quot;max&quot;</code>，请求模型所支持的最大推理预算（Ollama v0.21.3 加入）</li></ul><p>推理过程会显示在会话深入分析的<strong>推理标签页</strong>中。不支持推理的模型不会显示这个控件。</p><h3 id="输出格式控制-v0-4-7" tabindex="-1">输出格式控制（v0.4.7+） <a class="header-anchor" href="#输出格式控制-v0-4-7" aria-label="Permalink to &quot;输出格式控制（v0.4.7+）&quot;">​</a></h3><p>对话设置面板中的<strong>输出格式</strong>选择器可以强制结构化输出，共三种模式：</p><ul><li><strong>自由文本</strong> —— 无约束，默认值</li><li><strong>合法 JSON（任意结构）</strong> —— 发送 <code>format: &quot;json&quot;</code>，模型必须返回可解析的 JSON</li><li><strong>JSON Schema（严格）</strong> —— 把一个完整的 JSON Schema 对象作为 <code>format</code> 发送。界面会出现一个文本框供你粘贴任意合法 schema，并在你输入时实时校验 JSON。模型的输出会被严格约束为匹配该 schema。</li></ul><p>JSON Schema 模式在强制基准测试答案格式、校验 Agent 的工具输入、以及提取 RAG 引用时特别有用。</p><h3 id="回复质量检查" tabindex="-1">回复质量检查 <a class="header-anchor" href="#回复质量检查" aria-label="Permalink to &quot;回复质量检查&quot;">​</a></h3><p>每一条完成的助手回复都会自动经过五个客户端检测器的分析。发现问题时，回复的指标下方会出现彩色小标签：</p><table tabindex="0"><thead><tr><th>检测器</th><th>触发条件</th><th>严重程度</th></tr></thead><tbody><tr><td><strong>重复</strong></td><td>重复 4-gram 超过 50%</td><td>失败（红色）</td></tr><tr><td><strong>重复</strong></td><td>重复 4-gram 超过 30%</td><td>警告（黄色）</td></tr><tr><td><strong>拒答</strong></td><td>匹配 8 种常见拒答模式</td><td>警告</td></tr><tr><td><strong>乱码</strong></td><td>非 ASCII 字符超过 40%（文本长度 &gt; 20 字符）</td><td>警告</td></tr><tr><td><strong>空回复</strong></td><td>0 个词</td><td>失败</td></tr><tr><td><strong>空回复</strong></td><td>1–9 个词</td><td>警告</td></tr><tr><td><strong>截断</strong></td><td>达到 token 上限，或用掉超过 90% 预算却没有干净的结尾</td><td>警告</td></tr></tbody></table><p>指标行中还会出现一个彩色小圆点，便于快速扫视。如果全部检查通过，则不额外显示任何内容 —— 没有消息就是好消息。</p><div class="tip custom-block"><p class="custom-block-title">全部分析都在客户端完成</p><p>质量检查在你的浏览器中对显示出来的回复文本即时运行。没有 API 调用，没有外部服务。</p></div><h2 id="会话深入分析" tabindex="-1">会话深入分析 <a class="header-anchor" href="#会话深入分析" aria-label="Permalink to &quot;会话深入分析&quot;">​</a></h2><p>点击左侧面板中的任意会话，可以展开六个分析标签页：</p><h3 id="流式标签页" tabindex="-1">流式标签页 <a class="header-anchor" href="#流式标签页" aria-label="Permalink to &quot;流式标签页&quot;">​</a></h3><p>以可滚动列表展示每个 token 及其计时数据。列表上方的<strong>指标面板</strong>显示：</p><ul><li><strong>TTFT</strong>（首 token 时间）—— 模型开始回答所用的时间</li><li><strong>Token/秒</strong> —— 生成速度</li><li><strong>总 token 数</strong> —— 提示词与生成内容的 token 数量</li><li><strong>延迟图表</strong> —— token 之间延迟的可视化时间线</li></ul><h3 id="推理标签页" tabindex="-1">推理标签页 <a class="header-anchor" href="#推理标签页" aria-label="Permalink to &quot;推理标签页&quot;">​</a></h3><p>如果你运行的是 <strong>DeepSeek-R1</strong> 这类推理模型，<code>&lt;think&gt;</code> 块会被自动解析并逐步展示。每一个推理步骤会被归类为思考、观察、行动、结论或反思。</p><h3 id="内省标签页" tabindex="-1">内省标签页 <a class="header-anchor" href="#内省标签页" aria-label="Permalink to &quot;内省标签页&quot;">​</a></h3><p>层激活、注意力热力图和模型结构的可视化。</p><div class="warning custom-block"><p class="custom-block-title">示意性数据</p><p>这些可视化使用的是合成数据，用于演示真实内省会是什么样子。界面中已明确标注为「示意」。真正的内省需要 Ollama 并不暴露的模型内部数据。</p></div><h3 id="工具标签页" tabindex="-1">工具标签页 <a class="header-anchor" href="#工具标签页" aria-label="Permalink to &quot;工具标签页&quot;">​</a></h3><p>对话过程中模型发起的所有工具调用的时间线，包含：</p><ul><li>工具名称与参数</li><li>执行结果</li><li>耗时</li></ul><h3 id="agent-标签页" tabindex="-1">Agent 标签页 <a class="header-anchor" href="#agent-标签页" aria-label="Permalink to &quot;Agent 标签页&quot;">​</a></h3><p>一张状态流转图，展示 Agent 式提示词如何经过规划、工具调用和综合等步骤。</p><h3 id="提示词标签页" tabindex="-1">提示词标签页 <a class="header-anchor" href="#提示词标签页" aria-label="Permalink to &quot;提示词标签页&quot;">​</a></h3><p>对你的提示词的结构剖析，包含：</p><ul><li>识别出的各个部分（系统、用户、上下文、工具、示例）</li><li>每个部分的 token 数量</li><li>整体结构分析</li></ul><h2 id="小贴士" tabindex="-1">小贴士 <a class="header-anchor" href="#小贴士" aria-label="Permalink to &quot;小贴士&quot;">​</a></h2><ul><li><strong>会话持久化</strong> —— 所有对话都存储在 IndexedDB 中，刷新浏览器也不会丢失。</li><li><strong>中途切换模型</strong> —— 你可以在会话进行中切换模型，新模型会看到完整的对话历史。</li><li><strong>性能</strong> —— token 存储使用 <code>shallowRef</code>，以保证在数千个 token 时依然流畅。</li></ul>',53)])])}const m=o(l,[["render",i]]);export{k as __pageData,m as default};
